package com.example.nasconsports
import android.widget.*
import org.json.JSONObject
import org.json.JSONArray
import java.util.UUID
fun MainActivity.rosterScreen(){start("Club roster");val clubs=(data.optJSONArray("clubs")?:JSONArray()).objects();for(c in clubs){card(c.optString("name"),"Tenant: ${c.optString("tenant_id")}\nHome venue: ${c.optString("venue","Not supplied")}\n${c.optString("history","")}");val staff=c.optJSONArray("staff");if(staff!=null)text("Staff: "+(0 until staff.length()).joinToString(" • "){staff.optString(it)},14f)}
button("Refresh club & roster"){refresh{rosterScreen()}};val rosters=(data.optJSONArray("rosters")?:JSONArray()).objects();if(rosters.isEmpty()){card("No roster configured","Ask your organizer to prepare the competition demonstration.");return};for(r in rosters){text("Squad • ${r.getJSONObject("league").optString("league_id")}",20f,true);val squads=(r.optJSONArray("squads")?:JSONArray()).objects();val players=(r.optJSONArray("players")?:JSONArray()).objects();for(p in players){val sq=squads.find{it.optString("squad_id")==p.optString("squad_id")};val box=card(p.optString("name"),"${p.optString("position").uppercase()} • ${p.optString("role").replace('_',' ')}\n${sq?.optString("name")?:"Released"}");if(canRoster&&!p.isNull("squad_id")&&(role=="super_admin"||sq?.optString("club_id")=="club-alpha-1"))button("Manage player",box){rosterForm(r,p)}}}}
fun MainActivity.rosterForm(r:JSONObject,p:JSONObject){start("Roster action");card(p.optString("name"),"Current squad: ${p.optString("squad_id")}\nPosition: ${p.optString("position")}");val types=listOf("transfer","loan","release");val type=picker("Action",types);val squads=(r.optJSONArray("squads")?:JSONArray()).objects().filter{it.optString("squad_id")!=p.optString("squad_id")};val dest=picker("Destination (ignored for release)",squads.map{it.optString("name")});val today=java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.US).format(java.util.Date());val effective=field("Effective date • YYYY-MM-DD",today);val loanEnd=field("Loan end date • YYYY-MM-DD (loans only)","2026-12-01");val reason=field("Reason for this change");button("Review action"){val t=types[type.selectedItemPosition];if(reason.text.isBlank()){reason.error="A reason is required";return@button};if(!effective.text.toString().matches(Regex("\\d{4}-\\d{2}-\\d{2}"))){effective.error="Use YYYY-MM-DD";return@button};if(t!="release"&&squads.isEmpty()){notice("No destination squad is available.");return@button};val b=JSONObject().put("request_id",UUID.randomUUID().toString()).put("league_id",r.getJSONObject("league").getString("league_id")).put("player_id",p.getString("player_id")).put("type",t).put("from_squad_id",p.getString("squad_id")).put("to_squad_id",if(t=="release")JSONObject.NULL else squads[dest.selectedItemPosition].getString("squad_id")).put("effective_date",effective.text.toString()).put("loan_end_date",if(t=="loan")loanEnd.text.toString()else JSONObject.NULL).put("reason",reason.text.toString()).put("requested_by",user.getString("user_id"));val history=(r.optJSONArray("history")?:JSONArray()).objects().count{it.optString("player_id")==p.optString("player_id")};confirm("${t.replaceFirstChar{it.uppercase()}} ${p.optString("name")} effective ${effective.text}?\nReason: ${reason.text}\n"+if(online)"This will be submitted to the server."else"This will be queued on this device."){submitMutation("roster_transfer",history,b){if(online)refresh{rosterScreen()}else queueScreen()}}}}
